// Reproduce code for benchmarking JavaScript parsers (Cherow, Esprima, Acorn, Espree, Shift, Babylon)
// This code assumes you have installed the following npm packages:
// cherow, esprima, acorn, espree, shift-parser, @babel/parser

const fs = require('fs');
const path = require('path');
const cherow = require('cherow');
const esprima = require('esprima');
const acorn = require('acorn');
const espree = require('espree');
const shift = require('shift-parser');
const babelParser = require('@babel/parser');

const sources = [
  'jquery-1.9.1.js',
  'jquery.mobile-1.4.2.js',
  'angular-1.6.6.js',
  'react-0.13.3.js',
  'typescript-2.5.js',
];

const parsers = [
  {
    name: 'Cherow',
    parse: (code) => cherow.parse(code, { next: true, module: true }),
  },
  {
    name: 'Esprima',
    parse: (code) => esprima.parseScript(code),
  },
  {
    name: 'Acorn',
    parse: (code) => acorn.parse(code, { ecmaVersion: 2020, sourceType: 'module' }),
  },
  {
    name: 'Espree',
    parse: (code) => espree.parse(code, { ecmaVersion: 2020, sourceType: 'module' }),
  },
  {
    name: 'Shift',
    parse: (code) => shift.parseScript(code),
  },
  {
    name: 'Babylon',
    parse: (code) => babelParser.parse(code, { sourceType: 'module', plugins: ['jsx', 'flow'] }),
  },
];

function benchmarkParser(parser, code) {
  const start = process.hrtime();
  parser.parse(code);
  const diff = process.hrtime(start);
  return diff[0] * 1000 + diff[1] / 1e6; // ms
}

(async function runBenchmarks() {
  for (const sourceFile of sources) {
    const code = fs.readFileSync(path.join(__dirname, 'benchmarks', sourceFile), 'utf8');
    console.log(`\nBenchmarking: ${sourceFile}`);
    for (const parser of parsers) {
      try {
        const time = benchmarkParser(parser, code);
        console.log(`${parser.name}: ${time.toFixed(1)} ms`);
      } catch (e) {
        console.log(`${parser.name}: ERROR (${e.message})`);
      }
    }
  }
})();
